#include <bits/stdc++.h>
using namespace std;

const int MAXN = 10000;
const int MAXM = 2000000;
const int INF = 0x3f3f3f3f;

int n, m, k, c, d;

struct Edge
{
    int to, next, cap, flow, cost;
} edge[MAXM];
int head[MAXN], tol;
int pre[MAXN], dis[MAXN];
bool vis[MAXN];
int N; // total nodes, numbered from 0 to N-1
void init(int n)
{
    N = n;
    tol = 0;
    memset(head, -1, sizeof(head));
}
void addedge(int u, int v, int cap, int cost)
{
    edge[tol].to = v;
    edge[tol].cap = cap;
    edge[tol].cost = cost;
    edge[tol].flow = 0;
    edge[tol].next = head[u];
    head[u] = tol++;
    edge[tol].to = u;
    edge[tol].cap = 0;
    edge[tol].cost = -cost;
    edge[tol].flow = 0;
    edge[tol].next = head[v];
    head[v] = tol++;
}
bool spfa(int s, int t)
{
    queue<int> q;
    for (int i = 0; i < N; i++)
    {
        dis[i] = INF;
        vis[i] = false;
        pre[i] = -1;
    }
    dis[s] = 0;
    vis[s] = true;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        vis[u] = false;
        for (int i = head[u]; i != -1; i = edge[i].next)
        {
            int v = edge[i].to;
            if (edge[i].cap > edge[i].flow && dis[v] > dis[u] + edge[i].cost)
            {
                dis[v] = dis[u] + edge[i].cost;
                pre[v] = i;
                if (!vis[v])
                {
                    vis[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return pre[t] != -1;
}
int minCostMaxflow(int s, int t, int &cost)
{
    int flow = 0;
    cost = 0;
    while (spfa(s, t))
    {
        int Min = INF;
        for (int i = pre[t]; i != -1; i = pre[edge[i ^ 1].to])
        {
            if (Min > edge[i].cap - edge[i].flow)
                Min = edge[i].cap - edge[i].flow;
        }
        for (int i = pre[t]; i != -1; i = pre[edge[i ^ 1].to])
        {
            edge[i].flow += Min;
            edge[i ^ 1].flow -= Min;
            cost += edge[i].cost * Min;
        }
        flow += Min;
    }
    return flow;
}

int main()
{
    cin >> n >> m >> k >> c >> d;
    init(MAXN);
    for(int i = 0; i < k; i++)
    {
        int x;
        cin >> x;
        addedge(0, x, 1, 0);
    }
    for(int i = 0; i < 100; i++)
    {
        for(int j = 0; j < k; j++)
            addedge(1+i*n, 9999, 1, i*c);
    }
    for(int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        for(int j = 1; j < 100; j++)
        {
            for(int gg = 1; gg <= k; gg++)
            {
                addedge(u+(j-1)*n, v+j*n, 1, (2*gg-1)*d);
                addedge(v+(j-1)*n, u+j*n, 1, (2*gg-1)*d);
            }
        }
    }
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j < 100; j++)
        {
            addedge(i+(j-1)*n, i+j*n, k, 0);
        }
    }

    int cost;
    minCostMaxflow(0, 9999, cost);
    cout << cost << endl;
}
